$ErrorActionPreference = "Stop"
$here = Split-Path -Parent $MyInvocation.MyCommand.Path
$desktop = [Environment]::GetFolderPath("Desktop")
$ico = Join-Path $here "audiopheliac.ico"
$target = Join-Path $here "GO.cmd"
if (-not (Test-Path $target)) { throw "Missing GO.cmd. Run this from C:\Users\gillo\The-Audiopheliac\family-remote" }

if (-not (Test-Path $ico)) {
  $b64 = @'

'@
  [IO.File]::WriteAllBytes($ico, [Convert]::FromBase64String(($b64 -replace '\s','')))
}

$shell = New-Object -ComObject WScript.Shell
$path = Join-Path $desktop "The Audiopheliac.lnk"
$lnk = $shell.CreateShortcut($path)
$lnk.TargetPath = $target
$lnk.WorkingDirectory = $here
$lnk.IconLocation = $ico
$lnk.Description = "The Audiopheliac — family room remote"
$lnk.WindowStyle = 1
$lnk.Save()
Write-Host "Created $path"
Write-Host "Double-click The Audiopheliac, then on the tablets open:"
Write-Host "  http://192.168.1.119:8099"
